// Builds the generated parts of the skill from src/: the engine for scripts/build.mjs (scripts/engine.mjs: read, check,
// the facilitator's script, a game and its debrief, and chalk-talk's reader for the drawings) and the drill page with
// its code and chalk-talk's drawing inside (assets/drill.html). Run: npm run assets. Never edit the generated files.
import { build } from 'esbuild'
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const skill = join(root, 'skills/dress-rehearsal')
const chalk = JSON.parse(readFileSync(join(here, 'node_modules/chalk-talk/package.json'), 'utf8')).version
const banner = `// GENERATED by tools/assets.mjs (chalk-talk ${chalk}). Do not edit.`

// chalk-talk's contract alone (the recipe reader), not its renderer
const contract = join(here, 'node_modules/chalk-talk/scripts/contract.mjs')
const engine = await build({
  entryPoints: [join(root, 'src/engine.ts')],
  bundle: true, format: 'esm', platform: 'node', target: 'node18', minify: true, write: false, logLevel: 'warning',
  nodePaths: [join(here, 'node_modules')],
  alias: { 'chalk-contract': contract },
  banner: { js: "import { createRequire } from 'node:module'; const require = createRequire(import.meta.url);" },
})
writeFileSync(join(skill, 'scripts/engine.mjs'), `${banner}\n${engine.outputFiles[0].text}`)

const css = readFileSync(join(root, 'src/page/drill.css'), 'utf8')
const page = await build({
  entryPoints: [join(root, 'src/page/drill.ts')],
  bundle: true, format: 'iife', target: 'es2020', minify: true, write: false, logLevel: 'warning',
  nodePaths: [join(here, 'node_modules')],
})
const script = page.outputFiles[0].text
if (/<\/script/i.test(script)) throw new Error('The page script contains "</script": it would end the page early.')
const html = readFileSync(join(root, 'src/page/template.html'), 'utf8').replace(/\{\{(VERSION|CSS|JS)\}\}/g, (_, k) => ({ VERSION: `chalk-talk ${chalk}`, CSS: css, JS: script })[k])
if (!html.includes('{{DRILL}}')) throw new Error('The template lost its {{DRILL}} slot.')
writeFileSync(join(skill, 'assets/drill.html'), html)
writeFileSync(join(skill, 'assets/VERSION'), `chalk-talk ${chalk}\n`)
console.log(`✓ assets: engine.mjs ${(engine.outputFiles[0].text.length / 1024).toFixed(0)} KB, drill.html ${(html.length / 1024).toFixed(0)} KB (chalk-talk ${chalk})`)

// The npm package carries the command line (npx dress-rehearsal …).
mkdirSync(join(root, 'npm/scripts'), { recursive: true })
mkdirSync(join(root, 'npm/assets'), { recursive: true })
for (const f of ['build.mjs', 'engine.mjs']) copyFileSync(join(skill, 'scripts', f), join(root, 'npm/scripts', f))
copyFileSync(join(skill, 'assets/drill.html'), join(root, 'npm/assets/drill.html'))
copyFileSync(join(root, 'LICENSE'), join(root, 'npm/LICENSE'))
